import {useEffect,useMemo,useState} from 'react';
import {Pressable,StyleSheet,Text,View} from '@/platform/react-native';
import {useQuery} from '@tanstack/react-query';
import {router} from '@/router';
import {Ionicons} from '@/platform/icons';
import {api} from '@/lib/api';
import {useCommunity} from '@/store/community';
import {Badge,Card,EmptyState,Muted,Screen} from '@/components/UI';
import {colors} from '@/theme';
import type {Meeting} from '@/types';

const startOfDay=(value:Date)=>new Date(value.getFullYear(),value.getMonth(),value.getDate());
const sameDay=(left:Date,right:Date)=>left.getFullYear()===right.getFullYear()&&left.getMonth()===right.getMonth()&&left.getDate()===right.getDate();

export default function Calendar(){
 const c=useCommunity(s=>s.current);
 const{data=[]}=useQuery<Meeting[]>({queryKey:['meetings',c?.Id],enabled:!!c,queryFn:async()=>(await api.get(`/communities/${c!.Id}/meetings`)).data});
 const[clock,setClock]=useState(()=>new Date());
 const[cursor,setCursor]=useState(()=>new Date(clock.getFullYear(),clock.getMonth(),1));
 const[selectedDate,setSelectedDate]=useState<Date|null>(null);
 const days=['M','T','W','T','F','S','S'];
 useEffect(()=>{const tomorrow=new Date();tomorrow.setHours(24,0,0,0);const timer=setTimeout(()=>setClock(new Date()),Math.max(1000,tomorrow.getTime()-Date.now()+250));return()=>clearTimeout(timer)},[clock]);
 const upcoming=useMemo(()=>{const today=startOfDay(clock);return data.filter(meeting=>startOfDay(new Date(meeting.StartDateTime)).getTime()>=today.getTime()).sort((a,b)=>new Date(a.StartDateTime).getTime()-new Date(b.StartDateTime).getTime())},[data,clock]);
 const shown=selectedDate?upcoming.filter(meeting=>sameDay(new Date(meeting.StartDateTime),selectedDate)):upcoming;
 const eventDays=useMemo(()=>new Set(upcoming.filter(meeting=>{const date=new Date(meeting.StartDateTime);return date.getFullYear()===cursor.getFullYear()&&date.getMonth()===cursor.getMonth()}).map(meeting=>new Date(meeting.StartDateTime).getDate())),[upcoming,cursor]);
 return <Screen scroll><Card><View style={styles.monthHeader}><Text style={styles.month}>{cursor.toLocaleString(undefined,{month:'long',year:'numeric'})}</Text><View style={styles.arrows}><Pressable accessibilityRole="button" accessibilityLabel="Previous month" onPress={()=>{setCursor(new Date(cursor.getFullYear(),cursor.getMonth()-1,1));setSelectedDate(null)}}><Ionicons name="chevron-back" size={20} color={colors.muted}/></Pressable><Pressable accessibilityRole="button" accessibilityLabel="Next month" onPress={()=>{setCursor(new Date(cursor.getFullYear(),cursor.getMonth()+1,1));setSelectedDate(null)}}><Ionicons name="chevron-forward" size={20} color={colors.muted}/></Pressable></View></View><View style={styles.grid}>{days.map((day,index)=><Text key={index} style={styles.weekday}>{day}</Text>)}{Array.from({length:42},(_,index)=>{const offset=(new Date(cursor.getFullYear(),cursor.getMonth(),1).getDay()+6)%7;const day=index-offset+1;const max=new Date(cursor.getFullYear(),cursor.getMonth()+1,0).getDate();if(day<1||day>max)return <View key={index} style={styles.date}/>;const date=new Date(cursor.getFullYear(),cursor.getMonth(),day);const today=sameDay(date,clock),selected=!!selectedDate&&sameDay(date,selectedDate),selectedOther=selected&&!today,hasEvent=eventDays.has(day);return <Pressable key={index} accessibilityRole="button" accessibilityLabel={date.toLocaleDateString(undefined,{dateStyle:'full'})} accessibilityState={{selected}} onPress={()=>setSelectedDate(current=>current&&sameDay(current,date)?null:date)} style={({pressed})=>[styles.date,today&&styles.todayDate,selectedOther&&styles.selectedDate,pressed&&{opacity:.7}]}><Text style={[styles.dateText,today&&styles.todayText,selectedOther&&styles.selectedText]}>{day}</Text>{hasEvent?<View style={[styles.eventDot,today&&{backgroundColor:'#fff'},selectedOther&&{backgroundColor:colors.primary}]}/>:null}</Pressable>})}</View></Card><View style={styles.upcomingRow}><Text style={styles.upcoming}>{selectedDate?selectedDate.toLocaleDateString(undefined,{dateStyle:'long'}):'Upcoming'}</Text>{selectedDate?<Pressable accessibilityRole="button" accessibilityLabel="Show all upcoming events" onPress={()=>setSelectedDate(null)}><Text style={styles.showAll}>Show all</Text></Pressable>:null}</View>{!c?<EmptyState icon="calendar-outline" title="No community selected" body="Select a community to see its meetings."/>:shown.length?shown.map(meeting=><Pressable key={meeting.Id} accessibilityRole="button" accessibilityLabel={`Open ${meeting.Title}`} onPress={()=>router.push(`/community/${c.Id}/meetings` as any)}><Card style={styles.meeting}><View style={styles.marker}/><View style={{flex:1}}><Text style={styles.title}>{meeting.Title}</Text><Muted>{new Date(meeting.StartDateTime).toLocaleString([],{dateStyle:'medium',timeStyle:'short'})}</Muted><Muted>{meeting.Location||'Location not specified'}</Muted></View>{meeting.MyResponse?<Badge text={meeting.MyResponse.replace('_',' ')} tone={meeting.MyResponse==='GOING'?'green':'gray'}/>:null}</Card></Pressable>):<EmptyState icon="calendar-clear-outline" title={selectedDate?'Nothing on this date':'Nothing scheduled'} body={selectedDate?'Choose another date or show all upcoming events.':'Upcoming meetings and community events will appear here.'}/>}</Screen>
}

const styles=StyleSheet.create({monthHeader:{flexDirection:'row',justifyContent:'space-between',alignItems:'center',marginBottom:14},month:{fontSize:18,fontWeight:'900',color:colors.text},arrows:{flexDirection:'row',gap:14},grid:{flexDirection:'row',flexWrap:'wrap'},weekday:{width:'14.28%',textAlign:'center',fontSize:11,fontWeight:'800',color:colors.muted,paddingVertical:6},date:{width:'14.28%',height:46,alignItems:'center',justifyContent:'center'},todayDate:{backgroundColor:colors.primary,borderRadius:12},selectedDate:{backgroundColor:colors.primaryLight,borderRadius:12},dateText:{fontSize:13,color:colors.text,fontWeight:'700'},todayText:{color:'#fff'},selectedText:{color:colors.primary,fontWeight:'900'},eventDot:{position:'absolute',bottom:5,width:4,height:4,borderRadius:2,backgroundColor:colors.primary},upcomingRow:{flexDirection:'row',alignItems:'center',justifyContent:'space-between',marginBottom:12,marginTop:6},upcoming:{fontSize:18,fontWeight:'900',color:colors.text},showAll:{fontWeight:'800',color:colors.primary},meeting:{flexDirection:'row',gap:12,alignItems:'flex-start'},marker:{width:4,height:'100%',minHeight:52,borderRadius:4,backgroundColor:colors.primary},title:{fontSize:15,fontWeight:'900',color:colors.text}})
